import math
import hashlib

class BloomFilter:
    """
    A Bloom Filter implementation for probabilistic set membership testing.

    This implementation calculates the optimal size of the bit array and the
    ideal number of hash functions based on expected items and desired false 
    positive rate. It uses Python's built-in hashlib for hashing strings into 
    integers which are then used to set bits in the bit array.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        self.size = self._optimal_bit_array_size(expected_items, false_positive_rate)
        self.num_hashes = self._optimal_num_hash_functions(self.size, expected_items)
        self.bit_array = [0] * self.size

    def _optimal_bit_array_size(self, n: int, p: float) -> int:
        """Calculate the optimal size of the bit array."""
        return int(-n * math.log(p) / (math.log(2) ** 2))

    def _optimal_num_hash_functions(self, m: int, n: int) -> int:
        """Calculate the optimal number of hash functions."""
        return max(1, int((m / n) * math.log(2)))

    def _hashes(self, item: str) -> list:
        """Generate a list of hash values for the item."""
        hash_values = []
        for i in range(self.num_hashes):
            hash_result = hashlib.md5((item + str(i)).encode()).hexdigest()
            hash_values.append(int(hash_result, 16) % self.size)
        return hash_values

    def add(self, item: str) -> None:
        """Add an item to the Bloom Filter."""
        for hash_value in self._hashes(item):
            self.bit_array[hash_value] = 1

    def contains(self, item: str) -> bool:
        """Check if an item is in the Bloom Filter."""
        for hash_value in self._hashes(item):
            if self.bit_array[hash_value] == 0:
                return False
        return True

