import math
import hashlib

class BloomFilter:
    """
    A Bloom Filter implementation for efficient probabilistic set membership testing.

    This implementation calculates the optimal size of the bit array and the number of 
    hash functions based on expected items and desired false positive rate. It utilizes 
    hashlib for string hashing, and represents the bit array as an integer for memory efficiency,
    ensuring fewer issues with memory allocation and providing a compact representation.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        self.size = self._optimal_bit_array_size(expected_items, false_positive_rate)
        self.num_hashes = self._optimal_num_hash_functions(self.size, expected_items)
        self.bit_array = 0  # Representing bit array as an integer

    def _optimal_bit_array_size(self, n: int, p: float) -> int:
        """Calculate the optimal size of the bit array."""
        return max(1, int(-n * math.log(p) / (math.log(2) ** 2)))

    def _optimal_num_hash_functions(self, m: int, n: int) -> int:
        """Calculate the optimal number of hash functions."""
        return max(1, int((m / n) * math.log(2)))

    def _hashes(self, item: str) -> list:
        """Generate a list of hash values for the item using multiple hash functions."""
        return [int(hashlib.md5((item + str(i)).encode()).hexdigest(), 16) % self.size 
                    for i in range(self.num_hashes)]

    def add(self, item: str) -> None:
        """Add an item to the Bloom Filter."""
        for hash_value in self._hashes(item):
            self.bit_array |= (1 << hash_value)  # Set the bit at hash_value index

    def contains(self, item: str) -> bool:
        """Check if an item is in the Bloom Filter."""
        return all((self.bit_array >> hash_value) & 1 for hash_value in self._hashes(item))
